-- 隠し列の述語 —— その行を fields_hidden.from の外側のロールとして読める人かどうか。
-- 呼び出した人の権限で評価する(security invoker)—— 述語はその表の RLS のポリシーと同じ式で、実行者の解決は
-- 土台の関数と補助関数(security definer)に委ねる。面のロールが行を作って直接呼んでも、RLS で見えない行は読めない
-- (定義者の権限で評価すると、親の状態を読む述語が RLS で見えない行を探る口になる)。

-- 列 note / 見てよいロール: librarian
create or replace function api.can_see_holds_note(rec public.holds) returns boolean
language sql
stable
security invoker
set search_path = public
as $$
    select public.is_librarian();
$$;

revoke all on function api.can_see_holds_note(public.holds) from public;
grant execute on function api.can_see_holds_note(public.holds) to anon, authenticated, service_role;

-- ビュー本体。列は宣言の順に並べて書き、select * は使わない —— 外から見えるのは
-- 宣言した列だけである、を形にしている。security_invoker = true なので行の防御は
-- 元の表に張った RLS がそのまま効く(正は 1 つのまま)。
-- drop してから作り直すのは、create or replace view が列の名前・型・並びを変えられず
-- 追加を末尾にしか置けないためである(並びは宣言の順に保つ)。このビューは外の口が
-- 読む葉であり、ほかのビュー・関数から参照されていないので落としても連鎖しない。
-- 隠し列は「特権のある接続か、述語が真なら値・それ以外は空」で出す。特権のある接続は
-- 元々 RLS もバイパスするので、ここで新たに広げてはいない。
drop view if exists api.holds;

create view api.holds with (security_invoker = true) as
select
    t.id,
    t.item_id,
    t.patron_id,
    case when not api.is_end_user() or api.can_see_holds_note(t) then t.note else null end as note,
    t.state
from public.holds t;

-- 読みだけを一般の呼び出し主体へ開ける(書き込みの直接経路は作らない。全書き込みは
-- security definer の RPC を通る)。
grant select on api.holds to anon, authenticated;
grant all on api.holds to service_role;
